 * @param d
 * @return
 */
CG3_INLINE std::vector<std::vector<Point3d> > polylines(
        const Dcel &mesh,
        const Vec3d &norm,
        double d)
{
    SurfaceMesh m = cgal::surfaceMeshFromDcel(mesh);
    return polylines(m, norm, d);
}

